function addItem(groupId, type, obj, origInfo) {
    if (type === 'lineGroup') {
        obj.children.forEach(m => highlightablePairs[groupId].push({ type: 'wedge', obj: m, ...origInfo }));
    } else {
        highlightablePairs[groupId].push({ type, obj, ...origInfo });
    }
}

let currentHighlight = null;
function setHighlight(groupId) {
    Object.values(highlightablePairs).forEach(list => {
        list.forEach(item => {
            if (item.type === 'sprite') {
                item.obj.scale.copy(item.origScale);
            } else if (item.type === 'mesh') {
                item.obj.material.emissive.setHex(0x000000);
            } else if (item.type === 'line' || item.type === 'wedge') {
                item.obj.material.color.setHex(item.origColor);
            }
        });
    });

    currentHighlight = groupId;
    if (!groupId) return;

    const list = highlightablePairs[groupId];
    if (list) {
        list.forEach(item => {
            if (item.type === 'sprite') {
                item.obj.scale.copy(item.origScale).multiplyScalar(1.25);
            } else if (item.type === 'mesh') {
                item.obj.material.emissive.setHex(0x444444);
            } else if (item.type === 'line' || item.type === 'wedge') {
                item.obj.material.color.setHex(0xffaa00);
            }
        });
    }
}

