function createTextSprite(text, color, scale = 1.0) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const fontSize = 64;
    ctx.font = `bold ${fontSize}px sans-serif`;
    const metrics = ctx.measureText(text);
    const textWidth = Math.ceil(metrics.width);
    const w = THREE.MathUtils.ceilPowerOfTwo(textWidth + 32);
    const h = THREE.MathUtils.ceilPowerOfTwo(fontSize + 32);
    canvas.width = w;
    canvas.height = h;

    ctx.font = `bold ${fontSize}px sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(text, w/2, h/2);

    const tex = new THREE.CanvasTexture(canvas);
    tex.minFilter = THREE.LinearFilter;
    const mat = new THREE.SpriteMaterial({ map: tex, transparent: true });
    const sprite = new THREE.Sprite(mat);
    sprite.scale.set((w/fontSize) * 0.4 * scale, (h/fontSize) * 0.4 * scale, 1);
    return sprite;
}

function create2DSolidLine(start, end) {
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    const geom = new THREE.CylinderGeometry(0.02, 0.02, len, 8);
    geom.translate(0, len/2, 0);
    const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color: 0x000000 }));
    mesh.position.copy(start);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
    return mesh;
}

function create2DDashedLine(start, end) {
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    const dashes = 5;
    const dashLen = len / (dashes * 2 - 1);
    const group = new THREE.Group();
    const geom = new THREE.CylinderGeometry(0.02, 0.02, dashLen, 8);
    geom.translate(0, dashLen/2, 0);
    const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });

    for(let i=0; i<dashes; i++) {
        const mesh = new THREE.Mesh(geom, mat);
        mesh.position.set(0, i * 2 * dashLen, 0);
        group.add(mesh);
    }

    group.position.copy(start);
    group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
    return group;
}

function create2DWedge(start, end) {
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    const width = 0.25;
    const shape = new THREE.Shape();
    shape.moveTo(0, 0);
    shape.lineTo(width/2, len);
    shape.lineTo(-width/2, len);
    shape.lineTo(0, 0);

    const geom = new THREE.ExtrudeGeometry(shape, { depth: 0.02, bevelEnabled: false });
    geom.translate(0, 0, -0.01);
    const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color: 0x000000 }));
    mesh.position.copy(start);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
    return mesh;
}

