function createTextSprite(text, color, scale = 1.0) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const fontSize = 64;
    ctx.font = `bold ${fontSize}px sans-serif`;
    const metrics = ctx.measureText(text);
    const textWidth = Math.ceil(metrics.width);
    const w = THREE.MathUtils.ceilPowerOfTwo(textWidth + 32);
    const h = THREE.MathUtils.ceilPowerOfTwo(fontSize + 32);
    canvas.width = w;
    canvas.height = h;

    ctx.font = `bold ${fontSize}px sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(text, w/2, h/2);

    const tex = new THREE.CanvasTexture(canvas);
    tex.minFilter = THREE.LinearFilter;
    const mat = new THREE.SpriteMaterial({ map: tex, transparent: true });
    const sprite = new THREE.Sprite(mat);
    sprite.scale.set((w/fontSize) * 0.4 * scale, (h/fontSize) * 0.4 * scale, 1);
    return sprite;
}

function create2DSolidLine(start, end) {
