// --- Highlighting Logic ---
const highlightGroups = { 'H': [], 'HO': [], 'CO2H': [] };

function addHighlight(name, obj, isHTML = false) {
    if (!highlightGroups[name]) highlightGroups[name] = [];
    if (isHTML) {
        highlightGroups[name].push({ type: 'html', el: obj.div, origColor: obj.div.style.color });
    } else if (obj instanceof THREE.Group) {
        obj.children.forEach(c => addHighlight(name, c));
    } else if (obj.material) {
        const c = obj.material.emissive ? obj.material.emissive.getHex() : obj.material.color.getHex();
        highlightGroups[name].push({ type: 'mesh', obj: obj, origColor: c });
    }
}

function setHighlight(groupId) {
    Object.values(highlightGroups).forEach(list => {
        list.forEach(item => {
            if (item.type === 'html') {
                item.el.style.color = item.origColor;
                item.el.style.textShadow = 'none';
                item.el.style.fontWeight = 'normal';
            } else if (item.type === 'mesh') {
                if (item.obj.material.emissive) item.obj.material.emissive.setHex(0x000000);
                else item.obj.material.color.setHex(item.origColor);
            }
        });
    });

    if (!groupId) return;

    const list = highlightGroups[groupId];
    if (list) {
        list.forEach(item => {
            if (item.type === 'html') {
                item.el.style.color = '#ffaa00';
                item.el.style.textShadow = '0 0 4px #ffaa00';
                item.el.style.fontWeight = 'bold';
            } else if (item.type === 'mesh') {
                if (item.obj.material.emissive) item.obj.material.emissive.setHex(0x555555);
                else item.obj.material.color.setHex(0xffaa00);
            }
        });
    }
}

// --- 2D Structure ---
function createThickLine(start, end, width = 0.04) {
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    const geom = new THREE.PlaneGeometry(width, len);
    const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color: 0x000000 }));
    mesh.position.copy(start).add(dir.multiplyScalar(0.5));
    mesh.rotation.z = Math.atan2(dir.y, dir.x) - Math.PI / 2;
    return mesh;
}

function createThickDashedLine(start, end, width = 0.04) {
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    const dashes = 4;
    const dashLen = len / (dashes * 2 - 1);
    const group = new THREE.Group();
    const geom = new THREE.PlaneGeometry(width, dashLen);
    const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
    for(let i = 0; i < dashes; i++) {
        const mesh = new THREE.Mesh(geom, mat);
        mesh.position.set(0, i * 2 * dashLen + dashLen / 2, 0);
        group.add(mesh);
    }
    group.position.copy(start);
    group.rotation.z = Math.atan2(dir.y, dir.x) - Math.PI / 2;
    return group;
}

function createWedge(start, end, width) {
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    const shape = new THREE.Shape();
    shape.moveTo(0, 0);
    shape.lineTo(width / 2, len);
    shape.lineTo(-width / 2, len);
    shape.lineTo(0, 0);
    const geom = new THREE.ShapeGeometry(shape);
    const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color: 0x000000 }));
    mesh.position.copy(start);
    mesh.rotation.z = Math.atan2(dir.y, dir.x) - Math.PI / 2;
    return mesh;
}

group2D.add(createThickLine(new THREE.Vector3(0, 0.45, 0), new THREE.Vector3(0, -0.45, 0)));

const dashH1 = createThickDashedLine(new THREE.Vector3(0, 0.75, 0), new THREE.Vector3(0, 1.4, 0));
const dashH2 = createThickDashedLine(new THREE.Vector3(0, -0.75, 0), new THREE.Vector3(0, -1.4, 0));
const wHO1 = createWedge(new THREE.Vector3(-0.15, 0.6, 0), new THREE.Vector3(-1.0, 0.6, 0), 0.2);
const wCO1 = createWedge(new THREE.Vector3(0.15, 0.6, 0), new THREE.Vector3(1.0, 0.6, 0), 0.2);
const wHO2 = createWedge(new THREE.Vector3(-0.15, -0.6, 0), new THREE.Vector3(-1.0, -0.6, 0), 0.2);
const wCO2 = createWedge(new THREE.Vector3(0.15, -0.6, 0), new THREE.Vector3(1.0, -0.6, 0), 0.2);

group2D.add(dashH1, dashH2, wHO1, wCO1, wHO2, wCO2);

function makeInteractive(mesh, groupName) {
    if (mesh instanceof THREE.Group) mesh.children.forEach(c => makeInteractive(c, groupName));
    else {
        registerInteractive(mesh, {
            title: `${groupName} Group`,
            body: 'Notice how this group perfectly reflects across the symmetry plane to its counterpart.',
            onClick: () => setHighlight(groupName)
        });
        addHighlight(groupName, mesh);
    }
}
makeInteractive(dashH1, 'H'); makeInteractive(dashH2, 'H');
makeInteractive(wHO1, 'HO'); makeInteractive(wHO2, 'HO');
makeInteractive(wCO1, 'CO2H'); makeInteractive(wCO2, 'CO2H');

const labels2D = [
    { entry: addLabel('C', new THREE.Vector3(), { fontSize: '18px' }), offset: new THREE.Vector3(0, 0.6, 0) },
    { entry: addLabel('C', new THREE.Vector3(), { fontSize: '18px' }), offset: new THREE.Vector3(0, -0.6, 0) },
    { entry: addLabel('H', new THREE.Vector3(), { color: '#008080', fontSize: '18px' }), offset: new THREE.Vector3(0, 1.6, 0) },
    { entry: addLabel('H', new THREE.Vector3(), { color: '#008080', fontSize: '18px' }), offset: new THREE.Vector3(0, -1.6, 0) },
    { entry: addLabel('HO', new THREE.Vector3(), { color: '#cc0066', fontSize: '18px' }), offset: new THREE.Vector3(-1.35, 0.6, 0) },
    { entry: addLabel('HO', new THREE.Vector3(), { color: '#cc0066', fontSize: '18px' }), offset: new THREE.Vector3(-1.35, -0.6, 0) },
    { entry: addLabel('CO<sub>2</sub>H', new THREE.Vector3(), { color: '#008000', fontSize: '18px' }), offset: new THREE.Vector3(1.45, 0.6, 0) },
    { entry: addLabel('CO<sub>2</sub>H', new THREE.Vector3(), { color: '#008000', fontSize: '18px' }), offset: new THREE.Vector3(1.45, -0.6, 0) }
];
addHighlight('H', labels2D[2].entry, true); addHighlight('H', labels2D[3].entry, true);
addHighlight('HO', labels2D[4].entry, true); addHighlight('HO', labels2D[5].entry, true);
addHighlight('CO2H', labels2D[6].entry, true); addHighlight('CO2H', labels2D[7].entry, true);

const lblSymm = addLabel('Symmetry plane', new THREE.Vector3(0, 0, 0), { fontSize: '15px' });

// --- Symmetry Planes ---
const planeShape = new THREE.Shape();
const pw = 3.6, ph = 0.9, pskew = 0.8;
planeShape.moveTo(-pw / 2, -ph / 2);
planeShape.lineTo(pw / 2, -ph / 2);
planeShape.lineTo(pw / 2 + pskew, ph / 2);
planeShape.lineTo(-pw / 2 + pskew, ph / 2);
planeShape.lineTo(-pw / 2, -ph / 2);
const planeGeom = new THREE.ShapeGeometry(planeShape);
const planeMat = new THREE.MeshBasicMaterial({ color: 0xaaddff, transparent: true, opacity: 0.6, side: THREE.DoubleSide, depthWrite: false });

const plane2D = new THREE.Mesh(planeGeom, planeMat);
plane2D.position.set(-2.5, 0, -0.1);
scene.add(plane2D);

const plane3D = new THREE.Mesh(planeGeom, planeMat);
plane3D.position.set(2.5, 0, -0.05); // slightly back to avoid Z-fighting with vertical C-C bond
scene.add(plane3D);

// --- 3D Model ---
const matC = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.6 });
const matH = new THREE.MeshStandardMaterial({ color: 0x44aaff, roughness: 0.6 });
const matO = new THREE.MeshStandardMaterial({ color: 0xcc0000, roughness: 0.6 });
const matCO2H = new THREE.MeshStandardMaterial({ color: 0x33aa33, roughness: 0.6 });
const geomSphere = new THREE.SphereGeometry(1, 32, 32);

function createAtom(mat, r, pos, groupName = null) {
    const mesh = new THREE.Mesh(geomSphere, mat);
    mesh.scale.setScalar(r);
    mesh.position.copy(pos);
    group3D.add(mesh);
    if (groupName) {
        addHighlight(groupName, mesh);
        registerInteractive(mesh, { 
            title: `${groupName} Group (3D)`, 
            body: 'Notice how this group perfectly reflects across the symmetry plane to its counterpart.',
            onClick: () => setHighlight(groupName)
        });
    }
    return mesh;
}

function createBond(p1, p2) {
    const dir = new THREE.Vector3().subVectors(p2, p1);
    const len = dir.length();
    const geom = new THREE.CylinderGeometry(0.05, 0.05, len, 8);
    geom.translate(0, len / 2, 0);
    const mesh = new THREE.Mesh(geom, new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.5 }));
    mesh.position.copy(p1);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
    group3D.add(mesh);
}

function createDoubleBond(p1, p2) {
    const dir = new THREE.Vector3().subVectors(p2, p1);
    const len = dir.length();
    const geom = new THREE.CylinderGeometry(0.04, 0.04, len, 8);
    geom.translate(0, len / 2, 0);
    const mat = new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.5 });
    let up = new THREE.Vector3(0, 0, 1);
    if (Math.abs(dir.clone().normalize().z) > 0.9) up.set(0, 1, 0);
    const perp = new THREE.Vector3().crossVectors(dir, up).normalize().multiplyScalar(0.06);

    const b1 = new THREE.Mesh(geom, mat);
    b1.position.copy(p1).add(perp);
    b1.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
    const b2 = new THREE.Mesh(geom, mat);
    b2.position.copy(p1).sub(perp);
    b2.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
    group3D.add(b1, b2);
}

const posC1 = new THREE.Vector3(0, 0.7, 0);
const posC2 = new THREE.Vector3(0, -0.7, 0);
createAtom(matC, 0.22, posC1);
createAtom(matC, 0.22, posC2);
createBond(posC1, posC2);

const buildHalf = (cPos, sign) => {
    const H = new THREE.Vector3(0, 1.0 * sign, -0.848);
    const O = new THREE.Vector3(-0.734, 1.0 * sign, 0.424);
    const CO = new THREE.Vector3(0.734, 1.0 * sign, 0.424);

    createAtom(matH, 0.15, H, 'H');
    createBond(cPos, H);

    createAtom(matO, 0.18, O, 'HO');
    createBond(cPos, O);
    const H_O = new THREE.Vector3(-1.034, 1.3 * sign, 0.624);
    createAtom(matH, 0.12, H_O, 'HO');
    createBond(O, H_O);

    createAtom(matCO2H, 0.18, CO, 'CO2H');
    createBond(cPos, CO);
    const O1 = new THREE.Vector3(1.3, 1.4 * sign, 0.3);
    const O2 = new THREE.Vector3(1.1, 0.5 * sign, 0.7);
    const CO_H = new THREE.Vector3(1.5, 0.3 * sign, 0.8);
    createAtom(matCO2H, 0.18, O1, 'CO2H');
    createAtom(matCO2H, 0.18, O2, 'CO2H');
    createAtom(matCO2H, 0.14, CO_H, 'CO2H');
    createDoubleBond(CO, O1);
    createBond(CO, O2);
    createBond(O2, CO_H);
};

buildHalf(posC1, 1);
buildHalf(posC2, -1);
group3D.rotation.y = -0.15; // slight angle to emphasize 3D depth while maintaining visual symmetry

// --- Layout & Animation ---
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 90,
  elevationDeg: 0,
  heightFraction: 0.75
});

let target2DX = -2.5, target3DX = 2.5;

function transitionLoop() {
    requestAnimationFrame(transitionLoop);
    group2D.position.x += (target2DX - group2D.position.x) * 0.12;
    group3D.position.x += (target3DX - group3D.position.x) * 0.12;
    plane2D.position.x = group2D.position.x;
    plane3D.position.x = group3D.position.x;

    labels2D.forEach(lbl => {
        lbl.entry.pos.set(group2D.position.x + lbl.offset.x, lbl.offset.y, lbl.offset.z);
    });
}
transitionLoop();

