// 2D Structure: Lines, Dashed Lines, Wedges (Shapes), HTML Labels. Symmetry plane is a skewed 2D shape.
// 3D Model: Spheres (Atoms), Cylinders (Bonds). Symmetry plane is a skewed 2D shape to match 2D visual style.

scene.background = new THREE.Color(0xffffff);

const ambLight = new THREE.AmbientLight(0xffffff, 0.7);
scene.add(ambLight);
const dirLight1 = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight1.position.set(2, 5, 4);
scene.add(dirLight1);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.3);
dirLight2.position.set(-3, -2, -2);
scene.add(dirLight2);

const group2D = new THREE.Group();
const group3D = new THREE.Group();
group2D.position.set(-2.5, 0, 0);
group3D.position.set(2.5, 0, 0);
scene.add(group2D);
scene.add(group3D);

// --- Highlighting Logic ---
const highlightGroups = { 'H': [], 'HO': [], 'CO2H': [] };

function addHighlight(name, obj, isHTML = false) {
    if (!highlightGroups[name]) highlightGroups[name] = [];
    if (isHTML) {
        highlightGroups[name].push({ type: 'html', el: obj.div, origColor: obj.div.style.color });
    } else if (obj instanceof THREE.Group) {
        obj.children.forEach(c => addHighlight(name, c));
    } else if (obj.material) {
        const isStandard = !!obj.material.emissive;
        const c = isStandard ? obj.material.emissive.getHex() : obj.material.color.getHex();
        highlightGroups[name].push({ type: 'mesh', obj: obj, origColor: c, isStandard });
    }
}

function setHighlight(groupId) {
    Object.values(highlightGroups).forEach(list => {
        list.forEach(item => {
            if (item.type === 'html') {
                item.el.style.color = item.origColor;
                item.el.style.textShadow = 'none';
                item.el.style.fontWeight = 'normal';
            } else if (item.type === 'mesh') {
                if (item.isStandard) {
                    item.obj.material.emissive.setHex(0x000000);
                } else {
                    item.obj.material.color.setHex(item.origColor);
                }
            }
        });
    });

    if (!groupId) return;

    const list = highlightGroups[groupId];
    if (list) {
        list.forEach(item => {
            if (item.type === 'html') {
                item.el.style.color = '#ff8800';
                item.el.style.textShadow = '0 0 5px #ffaa00';
                item.el.style.fontWeight = 'bold';
            } else if (item.type === 'mesh') {
                if (item.isStandard) {
                    item.obj.material.emissive.setHex(0x664400);
                } else {
                    item.obj.material.color.setHex(0xffaa00);
                }
            }
        });
    }
}

function makeInteractive(mesh, groupName, tooltipText) {
    if (mesh instanceof THREE.Group) {
        mesh.children.forEach(c => makeInteractive(c, groupName, tooltipText));
    } else {
        mesh.userData = { groupName, tooltip: tooltipText };
        addHighlight(groupName, mesh);
    }
}

// --- 2D Structure ---
function createThickLine(start, end, width = 0.04) {
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    const geom = new THREE.PlaneGeometry(width, len);
    const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color: 0x000000 }));
    mesh.position.copy(start).add(dir.multiplyScalar(0.5));
    mesh.rotation.z = Math.atan2(dir.y, dir.x) - Math.PI / 2;
    return mesh;
}

function createThickDashedLine(start, end, width = 0.04) {
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    const dashes = 4;
    const dashLen = len / (dashes * 2 - 1);
    const group = new THREE.Group();
    const geom = new THREE.PlaneGeometry(width, dashLen);
    const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
    for(let i = 0; i < dashes; i++) {
        const mesh = new THREE.Mesh(geom, mat);
        mesh.position.set(0, i * 2 * dashLen + dashLen / 2, 0);
        group.add(mesh);
    }
    group.position.copy(start);
    group.rotation.z = Math.atan2(dir.y, dir.x) - Math.PI / 2;
    return group;
}

function createWedge(start, end, width) {
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    const shape = new THREE.Shape();
    shape.moveTo(0, 0);
    shape.lineTo(width / 2, len);
    shape.lineTo(-width / 2, len);
    shape.lineTo(0, 0);
    const geom = new THREE.ShapeGeometry(shape);
    const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color: 0x000000 }));
    mesh.position.copy(start);
    mesh.rotation.z = Math.atan2(dir.y, dir.x) - Math.PI / 2;
    return mesh;
}

const cTopY = 0.6;
const cBotY = -0.6;

const lineCenter = createThickLine(new THREE.Vector3(0, cTopY - 0.15, 0), new THREE.Vector3(0, cBotY + 0.15, 0));
group2D.add(lineCenter);

const dashH1 = createThickDashedLine(new THREE.Vector3(0, cTopY + 0.15, 0), new THREE.Vector3(0, cTopY + 0.8, 0));
const dashH2 = createThickDashedLine(new THREE.Vector3(0, cBotY - 0.15, 0), new THREE.Vector3(0, cBotY - 0.8, 0));
const wHO1 = createWedge(new THREE.Vector3(-0.15, cTopY, 0), new THREE.Vector3(-0.9, cTopY, 0), 0.2);
const wCO1 = createWedge(new THREE.Vector3(0.15, cTopY, 0), new THREE.Vector3(0.9, cTopY, 0), 0.2);
const wHO2 = createWedge(new THREE.Vector3(-0.15, cBotY, 0), new THREE.Vector3(-0.9, cBotY, 0), 0.2);
const wCO2 = createWedge(new THREE.Vector3(0.15, cBotY, 0), new THREE.Vector3(0.9, cBotY, 0), 0.2);

group2D.add(dashH1, dashH2, wHO1, wCO1, wHO2, wCO2);

makeInteractive(dashH1, 'H', '<b>H Atom</b><br>Dashed line means it points backward into the page.');
makeInteractive(dashH2, 'H', '<b>H Atom</b><br>Dashed line means it points backward into the page.');
makeInteractive(wHO1, 'HO', '<b>OH Group</b><br>Wedged line means it points forward out of the page.');
makeInteractive(wHO2, 'HO', '<b>OH Group</b><br>Wedged line means it points forward out of the page.');
makeInteractive(wCO1, 'CO2H', '<b>CO₂H Group</b><br>Wedged line means it points forward out of the page.');
makeInteractive(wCO2, 'CO2H', '<b>CO₂H Group</b><br>Wedged line means it points forward out of the page.');

const labels2D = [
    { entry: addLabel('C', new THREE.Vector3(), { fontSize: '18px' }), offset: new THREE.Vector3(0, cTopY, 0) },
    { entry: addLabel('C', new THREE.Vector3(), { fontSize: '18px' }), offset: new THREE.Vector3(0, cBotY, 0) },
    { id: 'H', entry: addLabel('H', new THREE.Vector3(), { color: '#006680', fontSize: '18px' }), offset: new THREE.Vector3(0, cTopY + 1.0, 0) },
    { id: 'H', entry: addLabel('H', new THREE.Vector3(), { color: '#006680', fontSize: '18px' }), offset: new THREE.Vector3(0, cBotY - 1.0, 0) },
    { id: 'HO', entry: addLabel('HO', new THREE.Vector3(), { color: '#cc0033', fontSize: '18px' }), offset: new THREE.Vector3(-1.25, cTopY, 0) },
    { id: 'HO', entry: addLabel('HO', new THREE.Vector3(), { color: '#cc0033', fontSize: '18px' }), offset: new THREE.Vector3(-1.25, cBotY, 0) },
    { id: 'CO2H', entry: addLabel('CO<sub>2</sub>H', new THREE.Vector3(), { color: '#008033', fontSize: '18px' }), offset: new THREE.Vector3(1.35, cTopY, 0) },
    { id: 'CO2H', entry: addLabel('CO<sub>2</sub>H', new THREE.Vector3(), { color: '#008033', fontSize: '18px' }), offset: new THREE.Vector3(1.35, cBotY, 0) }
];

labels2D.forEach(lbl => {
    if (lbl.id) addHighlight(lbl.id, lbl.entry, true);
});

const lblSymm = addLabel('Symmetry plane', new THREE.Vector3(0, 0, 0), { fontSize: '15px' });

// --- Symmetry Planes ---
const planeShape = new THREE.Shape();
const pw = 4.0, ph = 0.8, pskew = 0.6;
planeShape.moveTo(-pw / 2, -ph / 2);
planeShape.lineTo(pw / 2, -ph / 2);
planeShape.lineTo(pw / 2 + pskew, ph / 2);
planeShape.lineTo(-pw / 2 + pskew, ph / 2);
planeShape.lineTo(-pw / 2, -ph / 2);
const planeGeom = new THREE.ShapeGeometry(planeShape);
const planeMat = new THREE.MeshBasicMaterial({ color: 0xcceeff, transparent: true, opacity: 0.6, side: THREE.DoubleSide, depthWrite: false });

const plane2D = new THREE.Mesh(planeGeom, planeMat);
plane2D.position.set(-2.5, 0, -0.1);
scene.add(plane2D);

const plane3D = new THREE.Mesh(planeGeom, planeMat);
plane3D.position.set(2.5, 0, -0.05);
scene.add(plane3D);

// --- 3D Model ---
const matC = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.5 });
const matH_atom = new THREE.MeshStandardMaterial({ color: 0x22aaff, roughness: 0.5 });
const matO = new THREE.MeshStandardMaterial({ color: 0xd93333, roughness: 0.5 });
const matCO2H = new THREE.MeshStandardMaterial({ color: 0x33aa44, roughness: 0.5 });
const geomSphere = new THREE.SphereGeometry(1, 32, 32);

function createAtom(mat, r, pos, groupName = null, tooltipText = null) {
    const mesh = new THREE.Mesh(geomSphere, mat);
    mesh.scale.setScalar(r);
    mesh.position.copy(pos);
    if (groupName) {
        mesh.userData = { groupName, tooltip: tooltipText };
        addHighlight(groupName, mesh);
    }
    group3D.add(mesh);
    return mesh;
}

function createBond(p1, p2, groupName = null, tooltipText = null) {
    const dir = new THREE.Vector3().subVectors(p2, p1);
    const len = dir.length();
    const geom = new THREE.CylinderGeometry(0.05, 0.05, len, 8);
    geom.translate(0, len / 2, 0);
    const mat = new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.5 });
    const mesh = new THREE.Mesh(geom, mat);
    mesh.position.copy(p1);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
    if (groupName) {
        mesh.userData = { groupName, tooltip: tooltipText };
        addHighlight(groupName, mesh);
    }
    group3D.add(mesh);
}

function createDoubleBond(p1, p2, groupName = null, tooltipText = null) {
    const dir = new THREE.Vector3().subVectors(p2, p1);
    const len = dir.length();
    const geom = new THREE.CylinderGeometry(0.04, 0.04, len, 8);
    geom.translate(0, len / 2, 0);
    const mat = new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.5 });
    let up = new THREE.Vector3(0, 0, 1);
    if (Math.abs(dir.clone().normalize().z) > 0.9) up.set(0, 1, 0);
    const perp = new THREE.Vector3().crossVectors(dir, up).normalize().multiplyScalar(0.06);

    const b1 = new THREE.Mesh(geom, mat);
    b1.position.copy(p1).add(perp);
    b1.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
    const b2 = new THREE.Mesh(geom, mat);
    b2.position.copy(p1).sub(perp);
    b2.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());

    if (groupName) {
        b1.userData = { groupName, tooltip: tooltipText };
        b2.userData = { groupName, tooltip: tooltipText };
        addHighlight(groupName, b1);
        addHighlight(groupName, b2);
    }
    group3D.add(b1, b2);
}

const posC1 = new THREE.Vector3(0, cTopY, 0);
const posC2 = new THREE.Vector3(0, cBotY, 0);
createAtom(matC, 0.22, posC1);
createAtom(matC, 0.22, posC2);
createBond(posC1, posC2);

const bondLen = 0.9;
const dy = 0.33 * bondLen;
const dx = 0.81 * bondLen;
const dz = 0.47 * bondLen;
const dzH = 0.94 * bondLen;

const buildHalf = (cPos, sign) => {
    const H = new THREE.Vector3(0, cPos.y + dy * sign, -dzH);
    const O = new THREE.Vector3(-dx, cPos.y + dy * sign, dz);
    const CO = new THREE.Vector3(dx, cPos.y + dy * sign, dz);

    createAtom(matH_atom, 0.15, H, 'H', '<b>H Atom</b><br>Points backward (away from viewer) in the tetrahedral geometry.');
    createBond(cPos, H, 'H', '<b>H Atom</b><br>Points backward in 3D.');

    createAtom(matO, 0.20, O, 'HO', '<b>OH Group</b><br>Points forward in the tetrahedral geometry.');
    createBond(cPos, O, 'HO', '<b>OH Group</b><br>Points forward in 3D.');
    const H_O = new THREE.Vector3(O.x - 0.3, O.y + 0.4 * sign, O.z + 0.1);
    createAtom(matO, 0.13, H_O, 'HO', '<b>OH Group</b><br>H atom attached to Oxygen.');
    createBond(O, H_O, 'HO', '<b>OH Group</b>');

    createAtom(matCO2H, 0.22, CO, 'CO2H', '<b>CO₂H Group</b><br>Points forward in the tetrahedral geometry.');
    createBond(cPos, CO, 'CO2H', '<b>CO₂H Group</b><br>Points forward in 3D.');

    const O1 = new THREE.Vector3(CO.x + 0.1, CO.y + 0.5 * sign, CO.z - 0.3);
    const O2 = new THREE.Vector3(CO.x + 0.4, CO.y + 0.2 * sign, CO.z + 0.4);
    const CO_H = new THREE.Vector3(O2.x + 0.3, O2.y + 0.3 * sign, O2.z + 0.1);

    createAtom(matCO2H, 0.20, O1, 'CO2H', '<b>CO₂H Group</b><br>Double-bonded Oxygen.');
    createAtom(matCO2H, 0.20, O2, 'CO2H', '<b>CO₂H Group</b><br>Single-bonded Oxygen (points outward).');
    createAtom(matCO2H, 0.14, CO_H, 'CO2H', '<b>CO₂H Group</b><br>Hydrogen atom.');
    createDoubleBond(CO, O1, 'CO2H', '<b>CO₂H Group</b>');
    createBond(CO, O2, 'CO2H', '<b>CO₂H Group</b>');
    createBond(O2, CO_H, 'CO2H', '<b>CO₂H Group</b>');
};

buildHalf(posC1, 1);
buildHalf(posC2, -1);

// --- Layout & Animation ---
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 90,
  elevationDeg: 0,
  heightFraction: 0.75
});

let target2DX = -2.5, target3DX = 2.5;

function transitionLoop() {
    requestAnimationFrame(transitionLoop);
    group2D.position.x += (target2DX - group2D.position.x) * 0.12;
    group3D.position.x += (target3DX - group3D.position.x) * 0.12;
    plane2D.position.x = group2D.position.x;
    plane3D.position.x = group3D.position.x;

    labels2D.forEach(lbl => {
        lbl.entry.pos.set(group2D.position.x + lbl.offset.x, lbl.offset.y, lbl.offset.z);
    });
}
transitionLoop();

function setRepresentation(mode) {
    if (mode === 'Structure') {
        target2DX = 0; target3DX = 12;
        setTimeout(() => { if (target3DX === 12) { group3D.visible = false; plane3D.visible = false; } }, 400);
        group2D.visible = true; plane2D.visible = true;
        lblSymm.pos.set(2.0, 0, 0);
    } else if (mode === 'Model') {
        target2DX = -12; target3DX = 0;
        setTimeout(() => { if (target2DX === -12) { group2D.visible = false; plane2D.visible = false; } }, 400);
        group3D.visible = true; plane3D.visible = true;
        lblSymm.pos.set(-2.0, 0, 0);
    } else {
        target2DX = -2.5; target3DX = 2.5;
        group2D.visible = true; plane2D.visible = true;
        group3D.visible = true; plane3D.visible = true;
        lblSymm.pos.set(0, 0, 0);
    }
}

// --- Interactive Tooltips & Highlights ---
const expBox = document.getElementById('explanationBox');
const expTitle = document.getElementById('expTitle');
const expBody = document.getElementById('expBody');
const tooltipEl = document.getElementById('figTooltip');

function showLocalPopup(title, body) {
    expTitle.textContent = title;
    expBody.textContent = body;
    expBox.style.display = 'block';
}

document.getElementById('repSelect').addEventListener('change', (e) => {
    setRepresentation(e.target.value);
    expBox.style.display = 'none';
});

document.getElementById('btnDemo1').addEventListener('click', () => {
    document.getElementById('repSelect').value = 'Side-by-side';
    setRepresentation('Side-by-side');
    showLocalPopup('Meso Symmetry', 'A meso compound has chiral centers but an internal plane of symmetry makes the overall molecule achiral. Notice how the top half perfectly reflects across the plane onto the bottom half.');
});

document.getElementById('btnDemo2').addEventListener('click', () => {
    document.getElementById('repSelect').value = 'Model';
    setRepresentation('Model');
    showLocalPopup('3D Geometry', 'In the physical model, see how the wedged (forward) and dashed (backward) bonds from the 2D drawing translate directly to a 3D tetrahedral arrangement mirroring across the symmetry plane.');
});

let currentHover = null;
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();

canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;

    raycaster.setFromCamera(mouse, camera);
    const intersects = raycaster.intersectObjects(scene.children, true);

    let found = null;
    for (const hit of intersects) {
        let obj = hit.object;
        while (obj) {
            if (obj.userData?.groupName) {
                found = obj;
                break;
            }
            obj = obj.parent;
        }
        if (found) break;
    }

    if (found) {
        currentHover = found.userData.groupName;
        if (tooltipEl) {
            tooltipEl.innerHTML = found.userData.tooltip;
            tooltipEl.style.left = (e.clientX + 12) + 'px';
            tooltipEl.style.top = (e.clientY + 12) + 'px';
            tooltipEl.style.display = 'block';
        }
        canvas.style.cursor = 'pointer';
    } else {
        currentHover = null;
        if (tooltipEl) tooltipEl.style.display = 'none';
        canvas.style.cursor = 'default';
    }
});

canvas.addEventListener('click', () => {
    setHighlight(currentHover);
});

canvas.addEventListener('mouseleave', () => {
    if (tooltipEl) tooltipEl.style.display = 'none';
    currentHover = null;
});
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
